const iconColor: Record<string,string> = {Gmail:'#d65345','Microsoft 365':'#3378c8','IMAP':'#6370b4'};

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,'')}><RoutedBoundary><Switch>
    <Route path="/login" component={AuthPage}/><Route path="/register" component={AuthPage}/>
    <Route path="/forgot-password" component={AuthPage}/><Route path="/workspace/setup" component={AuthPage}/>
    <Route><MainRouter/></Route>
  </Switch></RoutedBoundary></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>;
}
function RoutedBoundary({children}:{children:any}) { const [location]=useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }

function MainRouter() {
  const [path] = useLocation();
  if (path.startsWith('/email/')) return <Shell><EmailDetail id={path.split('/')[2]}/></Shell>;
  if (!titles[path] && path !== '/') return <NotFound/>;
  return <Shell>{path === '/' || path === '/dashboard' ? <Dashboard/> : path === '/inbox' || ['/drafts','/sent','/starred','/archive','/trash','/search'].includes(path) ? <Mailbox path={path}/> : path === '/compose' ? <Compose/> : <DataPage path={path}/>}</Shell>;
}

function Shell({children}:{children:any}) {
  const [path,navigate] = useLocation(); const [mobileOpen,setMobileOpen]=useState(false);
  const [search,setSearch]=useState('');
  return <div className="app-shell">
    <aside className={`sidebar ${mobileOpen?'sidebar-open':''}`}>
      <div className="brand"><div className="brand-mark"><span></span><span></span><span></span></div><span>northstar</span><span className="prototype-pill">UI preview</span></div>
      <button className="workspace-switch" data-testid="button-workspace-switch"><span className="workspace-avatar">N</span><span className="workspace-copy"><b>Northstar Studio</b><small>Team workspace</small></span><ChevronDown size={15}/></button>
      <Link href="/compose" className="compose-button" data-testid="link-compose"><Plus size={16}/> Compose <kbd>C</kbd></Link>
      <nav className="side-nav" aria-label="Main navigation">
        {navGroups.map(group=><div className="nav-group" key={group.title}><div className="nav-label">{group.title}</div>{group.items.map(([href,label,icon])=>{
          const Icon=iconSet[icon]||Mail; const active=path===href || (href==='/inbox'&&path==='/');
          return <Link href={href} className={`nav-item ${active?'active':''}`} key={href} data-testid={`link-nav-${href.replaceAll('/','-').slice(1)}`}><Icon size={16}/><span>{label}</span>{href==='/inbox'&&<b className="nav-count">12</b>}{href==='/notifications'&&<i className="nav-dot"/>}</Link>;
        })}</div>)}
      </nav>
      <div className="sidebar-bottom"><div className="sync-status"><span className="sync-dot"/><div><b>All inboxes synced</b><small>Last checked just now</small></div><Check size={14}/></div><button className="profile-menu" data-testid="button-profile-menu"><span className="avatar avatar-blue">AM</span><span><b>Alex Morgan</b><small>Workspace admin</small></span><Ellipsis size={17}/></button></div>
    </aside>
    {mobileOpen&&<button className="mobile-scrim" aria-label="Close navigation" onClick={()=>setMobileOpen(false)}/>}
    <main className="main-area">
      <header className="topbar"><button className="mobile-menu icon-button" aria-label="Open menu" onClick={()=>setMobileOpen(!mobileOpen)}><Menu size={19}/></button><div className="crumb"><span>Northstar Studio</span><ChevronRight size={14}/><b>{titles[path] || (path.startsWith('/email/')?'Conversation':'Overview')}</b></div>
        <div className="top-actions"><label className="global-search"><Search size={16}/><input placeholder="Search all mail..." value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){sessionStorage.setItem('northstar-search-query',search);navigate('/search')}}} data-testid="input-global-search"/><kbd>⌘ K</kbd></label><button className="icon-button" aria-label="Help" data-testid="button-help"><CircleHelp size={18}/></button><Link href="/notifications" className="icon-button notification-trigger" aria-label="Notifications" data-testid="link-notifications"><Bell size={18}/><i/></Link><span className="avatar avatar-blue top-avatar">AM</span></div>
      </header>
      <div className="page-content">{children}</div>
      <div className="prototype-footer"><span className="prototype-dot"/> Prototype mode <span>•</span> UI only — no mail is sent or synced</div>
    </main>
  </div>;
}

function PageHeading({eyebrow,title,description,actions}:{eyebrow?:string;title:string;description?:string;actions?:any}) {
 return <div className="page-heading"><div>{eyebrow&&<div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1>{description&&<p>{description}</p>}</div>{actions&&<div className="heading-actions">{actions}</div>}</div>;
}
function Button({children,onClick,kind='secondary',icon:Icon,disabled=false,testId}:{children:any;onClick?:()=>void;kind?:string;icon?:any;disabled?:boolean;testId?:string}) {
 return <button className={`button button-${kind}`} onClick={onClick} disabled={disabled} data-testid={testId||'button-action'}>{Icon&&<Icon size={15}/>} {children}</button>;
}
function Dashboard() {
 const [,navigate]=useLocation();
 const [toast,setToast]=useState('');
 return <><PageHeading eyebrow="MONDAY, JUNE 17" title="Good morning, Alex" description="Here’s what’s happening across your shared inboxes." actions={<Button kind="primary" icon={Plus} onClick={()=>navigate('/compose')} testId="button-new-message">New message</Button>}/>
  <div className="welcome-strip"><div className="welcome-icon"><Inbox size={20}/></div><div><b>Your team’s command center</b><p>Three accounts are connected. Your conversations are together, but still yours to control.</p></div><Link href="/accounts" className="text-link">Manage accounts <ArrowRight size={14}/></Link></div>
  <div className="metric-grid"><Metric title="Open conversations" value="38" delta="7 need a reply" icon={Inbox} accent="blue"/><Metric title="Waiting on your team" value="12" delta="Across 2 shared inboxes" icon={Clock3} accent="amber"/><Metric title="Resolved today" value="24" delta="Team average · 18" icon={CheckCheck} accent="green"/><Metric title="Connected inboxes" value="3" delta="All accounts healthy" icon={Mail} accent="violet"/></div>
  <div className="dashboard-grid"><section className="panel overview-panel"><div className="panel-head"><div><h2>Needs your attention</h2><p>Priority conversations, across every account</p></div><Link href="/inbox" className="text-link">View inbox <ArrowRight size={14}/></Link></div><div className="attention-list">{mails.slice(0,4).map(mail=><MailRow key={mail.id} mail={mail} compact/>)}</div></section>
  <section className="panel activity-panel"><div className="panel-head"><div><h2>Team activity</h2><p>A little movement goes a long way</p></div><button className="icon-button" aria-label="More activity options"><MoreHorizontal size={17}/></button></div><div className="activity-feed"><ActivityItem initials="PS" tone="peach" text={<><b>Priya Shah</b> assigned a conversation to you</>} sub="Access issue after workspace migration" time="4 min ago"/><ActivityItem initials="JL" tone="mint" text={<><b>Jordan Lee</b> added a private note</>} sub="Website feedback — mobile navigation" time="18 min ago"/><ActivityItem initials="AM" tone="blue" text={<><b>You</b> resolved a conversation</>} sub="New vendor onboarding" time="32 min ago"/><ActivityItem initials="SP" tone="lavender" text={<><b>Samir Patel</b> moved a conversation to Finance</>} sub="June expense report" time="1 hr ago"/></div><Link href="/team" className="activity-link">See team workspace <ArrowRight size={14}/></Link></section></div>
  <section className="panel accounts-overview"><div className="panel-head"><div><h2>Connected inboxes</h2><p>One queue, three points of view</p></div><Link href="/accounts" className="text-link">Manage <ArrowRight size={14}/></Link></div><div className="account-mini-list">{accounts.map(a=><div className="account-mini" key={a.address}><span className="provider-mark" style={{'--provider':a.color} as any}>{a.provider==='Gmail'?'G':a.provider==='IMAP / SMTP'?'I':'M'}</span><div className="account-mini-copy"><b>{a.address}</b><small>{a.provider}</small></div><span className="status-pill"><i/>{a.status}</span><span className="account-count">{a.count} messages</span><span className="account-sync">{a.sync}</span></div>)}</div></section>
  <Toast message={toast} close={()=>setToast('')}/>
 </>;
}

function headingAction(path:string,setDialog:()=>void,goAdd:()=>void,notify:(s:string)=>void) {
 if(path==='/accounts'||path==='/settings/accounts')return <Button kind="primary" icon={Plus} onClick={goAdd}>Add account</Button>;
 if(path==='/team')return <Link href="/team/invite" className="button button-primary"><UserPlus size={15}/> Invite member</Link>;
 if(path.startsWith('/automation'))return <Button kind="primary" icon={Plus} onClick={setDialog}>Create rule</Button>;
 if(path==='/templates')return <Button kind="primary" icon={Plus} onClick={setDialog}>New template</Button>;
 if(path==='/webhooks')return <Button kind="primary" icon={Plus} onClick={setDialog}>Add endpoint</Button>;
 if(path==='/contacts')return <Button kind="primary" icon={Plus} onClick={()=>notify('Contact creation is a UI-only preview.')}>Add contact</Button>;
 if(path==='/notifications')return <Button onClick={()=>notify('Notifications marked as read in this local preview.')}>Mark all read</Button>;
 return null;
}
function Field({label,placeholder,type='text'}:{label:string;placeholder?:string;type?:string}) {return <label className="field"><span>{label}</span><input type={type} placeholder={placeholder} data-testid={`input-${label.toLowerCase().replaceAll(' ','-')}`}/></label>;}
function DataTable({kind,rows,onAction,query,setQuery}:{kind:string;rows:any[];onAction:(s:string)=>void;query:string;setQuery:(s:string)=>void}) {
 const filtered=rows.filter(row=>JSON.stringify(row).toLowerCase().includes(query.toLowerCase()));
 const teamMode=kind==='team'; const contactMode=kind==='contacts';
 return <section className="panel table-panel"><div className="table-toolbar"><div><b>{teamMode?'Workspace members':contactMode?'Your contacts':'Shared templates'}</b><span>{teamMode?'4 members · 3 active now':contactMode?'People across connected inboxes':'Reusable replies for a consistent team voice'}</span></div><div className="table-toolbar-actions"><label className="table-search"><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Search ${kind}…`} data-testid={`input-search-${kind}`}/></label><button className="icon-button" aria-label="Filter"><SlidersHorizontal size={16}/></button></div></div><div className="data-table-wrap"><table className="data-table"><thead><tr>{teamMode?<><th>Member</th><th>Role</th><th>Status</th><th>Assigned</th><th>Last active</th><th/></>:contactMode?<><th>Contact</th><th>Company</th><th>Conversations</th><th>Last interaction</th><th/></>:<><th>Template</th><th>Category</th><th>Used</th><th>Updated</th><th/></>}</tr></thead><tbody>{filtered.map((r,i)=><tr key={r.email||r.name} data-testid={`row-${kind}-${i}`}>{teamMode?<><td><div className="table-person"><span className={`avatar avatar-${r.tone}`}>{r.initials}</span><span><b>{r.name}</b><small>{r.email}</small></span></div></td><td><span className="role-pill">{r.role}</span></td><td><span className={`member-status ${r.status==='Active'?'active':'away'}`}><i/>{r.status}</span></td><td>{r.assigned} conversations</td><td>{r.last}</td></>:contactMode?<><td><div className="table-person"><span className="avatar avatar-blue">{r.name.split(' ').map((x:string)=>x[0]).join('')}</span><span><b>{r.name}</b><small>{r.email}</small></span></div></td><td>{r.company}</td><td>{r.conversations} conversations</td><td>{r.last}</td></>:<><td><div className="template-title"><span className="template-icon"><FileText size={15}/></span><b>{r.name}</b></div></td><td><span className="label-chip">{r.category}</span></td><td>{r.usage} times</td><td>{r.updated}</td></>}<td><button className="icon-button" aria-label={`More options for ${r.name}`} onClick={()=>onAction('Item actions are a UI-only preview.')}><Ellipsis size={17}/></button></td></tr>)}</tbody></table></div>{!filtered.length&&<div className="empty-state"><h3>No matches</h3><p>Try another search.</p></div>}</section>;
}
function RolesTable({onAction}:{onAction:(s:string)=>void}) {
 const permissions=['View conversations','Reply to customers','Assign conversations','Manage labels','Invite members','Manage accounts','Workspace settings'];
 const roles=[['Admin','Full workspace access','yes','yes','yes','yes','yes','yes','yes'],['Manager','Manage team operations','yes','yes','yes','yes','yes','yes','no'],['Agent','Work with assigned conversations','yes','yes','yes','yes','no','no','no'],['Observer','Read-only workspace access','yes','no','no','no','no','no','no']];
 return <><div className="role-intro"><ShieldCheck size={18}/><p>Thoughtful access keeps shared work private and predictable. Role changes here are illustrative only.</p></div><div className="panel permission-panel"><div className="permission-heading"><div><h2>Permission matrix</h2><p>What each workspace role can do</p></div><Button icon={Plus} onClick={()=>onAction('Custom roles require a connected backend.')}>Create role</Button></div><div className="permission-table-wrap"><table className="permission-table"><thead><tr><th>Permission</th>{roles.map(r=><th key={r[0]}><b>{r[0]}</b><small>{r[1]}</small></th>)}</tr></thead><tbody>{permissions.map((p,i)=><tr key={p}><td>{p}</td>{roles.map(r=><td key={r[0]}>{r[i+2]==='yes'?<span className="permission-yes"><Check size={14}/></span>:<span className="permission-no">—</span>}</td>)}</tr>)}</tbody></table></div></div></>;
}
function AIContent({path,onAction}:{path:string;onAction:(s:string)=>void}) {
 const [active,setActive]=useState<Record<string,boolean>>({});
 const modules=[{href:'/ai/summary',title:'Conversation summaries',description:'Catch up on longer threads with a concise recap.',icon:AlignLeft,status:'Available to preview'},{href:'/ai/reply',title:'Reply assistance',description:'Start from a suggested draft, then make it yours.',icon:MessageSquareText,status:'Human review required'},{href:'/ai/classification',title:'Email classification',description:'Suggested categories and labels for new mail.',icon:ScanSearch,status:'Not connected'},{href:'/ai/priority-sentiment',title:'Priority & sentiment',description:'Surface time-sensitive or emotionally charged messages.',icon:Gauge,status:'Not connected'},{href:'/ai/routing',title:'Smart routing',description:'Suggest who might be best placed to respond.',icon:Route,status:'Not connected'},{href:'/ai/auto-reply',title:'Auto-reply suggestions',description:'Draft a response for a teammate to review.',icon:Bot,status:'Always requires review'}];
 if(path==='/ai'||path==='/settings/ai')return <><div className="ai-banner"><div className="ai-banner-icon"><Sparkles size={22}/></div><div><span className="ai-kicker">OPTIONAL ASSISTANCE</span><h2>Useful when it helps. Quiet when it doesn’t.</h2><p>AI features are off by default in this UI preview. No message content is processed.</p></div><span className="ai-off"><i/> Off</span></div><div className="section-heading"><div><h2>AI capabilities</h2><p>Choose what your team wants to explore</p></div><Link href="/settings/ai" className="text-link">Privacy controls <ArrowRight size={14}/></Link></div><div className="ai-module-grid">{modules.map((m)=><div className="panel ai-module" key={m.href}><div className="ai-module-icon"><m.icon size={17}/></div><span className="ai-module-status">{m.status}</span><h3>{m.title}</h3><p>{m.description}</p><div className="ai-module-footer"><Link href={m.href} className="text-link">Explore <ArrowRight size={13}/></Link><button className={`switch ${active[m.href]?'on':''}`} role="switch" aria-checked={!!active[m.href]} onClick={()=>{setActive({...active,[m.href]:!active[m.href]});onAction('AI controls are local only; no model has been enabled.')}} aria-label={`Toggle ${m.title}`}><i/></button></div></div>)}</div><div className="usage-inline"><div><Sparkles size={16}/><b>AI usage this month</b></div><span>0 of 2,000 credits used</span><div className="usage-meter"><i/></div><small>Usage is sample content only. No AI requests are made.</small></div></>;
 const module=modules.find(m=>m.href===path)||modules[0];const ExampleIcon=module.icon;
 return <><div className="ai-detail-layout"><section className="panel ai-detail-panel"><div className="detail-module-icon"><ExampleIcon size={20}/></div><span className="ai-kicker">AI CAPABILITY · UI DEMO</span><h2>{module.title}</h2><p>{module.description}</p><div className="ai-demo-example"><div className="ai-demo-head"><span><Sparkles size={14}/> Example conversation</span><span className="preview-tag">Sample only</span></div><b>Re: Q3 brand direction — final files</b><p>“The updated identity deck is ready for your review. I added the alternate lockup we discussed…”</p><div className="ai-output"><span>Illustrative suggestion</span>{path==='/ai/summary'?<p>Maya shared the final identity deck and is waiting on sign-off before the campaign handoff.</p>:path==='/ai/reply'?<p>Thanks for sending this through, Maya. The alternate lockup looks great — we’ll review the full deck and get back to you shortly.</p>:<p>Suggested label: <b>Client · Design</b><br/>Suggested priority: <b>Normal</b></p>}</div></div><Button kind="primary" icon={Sparkles} onClick={()=>onAction('AI is not connected. This sample suggestion was not generated.')}>Try sample suggestion</Button><small className="ai-disclaimer">Example text is static. Nothing has been classified, summarized, or sent.</small></section><aside className="panel ai-privacy-card"><ShieldCheck size={19}/><h3>Controls stay with you</h3><p>AI tools are optional. Before using real assistance, connect a provider and review workspace data policies.</p><Link href="/settings/ai" className="text-link">Review AI controls <ArrowRight size={13}/></Link></aside></div><div className="section-heading"><div><h2>Related controls</h2><p>Decide how assistance fits your team</p></div></div><div className="settings-control-row"><span><b>Require human review</b><small>Keep a person in control of replies and decisions.</small></span><span className="enabled-label"><Check size={13}/> Always on</span></div><div className="settings-control-row"><span><b>Use message content</b><small>Message content is not processed in this UI-only preview.</small></span><span className="disabled-label">Not connected</span></div></>;
}
function ScheduleList({onAction}:{onAction:(s:string)=>void}) {
 const events=[['Follow up with Nina Williams','Partnership launch timing','Today · 2:30 PM','Reminder'],['Check in with Elliot Brooks','Renewal options for 2025','Tomorrow · 9:00 AM','Follow-up']];
 return <div className="schedule-list">{events.map((e,i)=><div className="schedule-row" key={e[0]}><span className="schedule-icon"><CalendarClock size={16}/></span><span className="schedule-title"><b>{e[0]}</b><small>{e[1]}</small></span><span className="schedule-time"><Clock size={13}/>{e[2]}</span><span className="schedule-type">{e[3]}</span><button className="icon-button" aria-label="Scheduled action options" onClick={()=>onAction('Scheduled actions are not executed in this prototype.')}><Ellipsis size={17}/></button></div>)}</div>;
}
function NotesPage({onAction}:{onAction:(s:string)=>void}) {
 return <><div className="note-banner"><StickyNote size={18}/><span><b>Internal notes stay internal.</b> They are visible only to your workspace, never included in customer replies.</span></div><div className="notes-grid">{mails.slice(0,4).map((m,i)=><article className="panel note-card" key={m.id}><div className="note-card-head"><span className={`avatar avatar-${i%2?'mint':'peach'}`}>{i%2?'JL':'PS'}</span><span><b>{i%2?'Jordan Lee':'Priya Shah'}</b><small>{i===0?'12 min ago':'Yesterday'}</small></span><button className="icon-button" aria-label="Note options" onClick={()=>onAction('Note actions are a UI-only preview.')}><Ellipsis size={16}/></button></div><p>{['We promised to send the revised deck before Thursday. Ask Maya if she needs the source files too.','I’ve asked the engineering team to confirm whether this is account-level or user-level access.','Invoice reviewed — PO number matches the project record. Ready for accounting.','Launch copy is approved. Waiting on final newsletter slot from the partner.'][i]}</p><Link href={`/email/${m.id}`} className="note-related"><Mail size={13}/>{m.subject}<ArrowRight size={13}/></Link></article>)}</div></>;
}
function AssignmentPage({onAction}:{onAction:(s:string)=>void}) {
 return <><div className="assignment-summary"><div className="panel assignment-stat"><span>Unassigned</span><b>6</b><small>Across all shared inboxes</small></div><div className="panel assignment-stat"><span>Assigned to you</span><b>8</b><small>2 high priority</small></div><div className="panel assignment-stat"><span>Team capacity</span><b>68%</b><small>43 conversations across 4 members</small></div></div><div className="panel table-panel"><div className="table-toolbar"><div><b>Needs an owner</b><span>Conversations waiting to be assigned</span></div><Button onClick={()=>onAction('Bulk assignment is a UI-only preview.')}>Assign all</Button></div><div className="assignment-list">{[mails[1],mails[5],mails[7]].map((m,i)=><div className="assignment-row" key={m.id}><span className={`provider-dot ${m.provider==='Gmail'?'gmail':m.provider==='IMAP'?'imap':'outlook'}`}>{m.provider==='Gmail'?'G':m.provider==='IMAP'?'I':'M'}</span><span className="assignment-subject"><b>{m.subject}</b><small>{m.sender} · {m.time}</small></span><span className={`priority-pill ${m.priority.toLowerCase()}`}><i/>{m.priority}</span><select aria-label={`Assign ${m.subject}`} defaultValue="Unassigned" onChange={()=>onAction('Assignment updates are preview-only.')}><option>Unassigned</option>{team.map(t=><option key={t.email}>{t.name}</option>)}</select><Link href={`/email/${m.id}`} className="text-link">Open <ArrowRight size={13}/></Link></div>)}</div></div></>;
}
