 return <div className="generic-page panel"><div className="empty-icon"><Mail size={21}/></div><h2>{titles[path]}</h2><p>{descriptions[path]||'Your workspace preferences are shown here.'}</p><Link href="/inbox" className="button button-secondary">Go to unified inbox <ArrowRight size={14}/></Link></div>;
