function AuthPage() {
 const [path]=useLocation(); const [toast,setToast]=useState('');
 const authConfig:Record<string,{title:string;subtitle:string;button:string;eyebrow:string}>={
  '/login':{title:'Welcome back.',subtitle:'Pick up where your team left off.',button:'Sign in',eyebrow:'SIGN IN'},
  '/register':{title:'Make room for good work.',subtitle:'Bring your team’s inboxes into one considered workspace.',button:'Create workspace',eyebrow:'GET STARTED'},
  '/forgot-password':{title:'Let’s get you back in.',subtitle:'Enter your work email and we’ll help you reset your password.',button:'Send reset instructions',eyebrow:'ACCOUNT RECOVERY'},
  '/workspace/setup':{title:'Set up your workspace.',subtitle:'A shared home for the inboxes your team works from.',button:'Continue to workspace',eyebrow:'WORKSPACE SETUP'}
 };
 const config=authConfig[path]||authConfig['/login'];const signup=path==='/register';const forgot=path==='/forgot-password';
 return <div className="auth-screen"><div className="auth-aside"><Link href="/login" className="brand auth-brand"><div className="brand-mark"><span/><span/><span/></div><span>northstar</span></Link><div className="auth-quote"><div className="quote-mark">“</div><h2>Good work happens when everyone knows what’s next.</h2><p>One focused place for every conversation that matters.</p><div className="auth-people"><div className="team-face-row">{team.slice(0,3).map(m=><span key={m.email} className={`avatar avatar-${m.tone}`}>{m.initials}</span>)}</div><span>Built for thoughtful teams</span></div></div><div className="auth-aside-bottom">Shared inboxes, clearer days.</div></div><main className="auth-main"><div className="auth-card"><span className="eyebrow">{config.eyebrow}</span><h1>{config.title}</h1><p>{config.subtitle}</p>{!forgot&&<div className="auth-social"><Button onClick={()=>setToast('External sign-in is not available in this prototype.')}><span className="google-mark">G</span> Continue with Google</Button><Button onClick={()=>setToast('External sign-in is not available in this prototype.')}><span className="ms-mark">M</span> Microsoft 365</Button></div>}<div className="auth-divider"><span>or use your email</span></div><form onSubmit={e=>{e.preventDefault();setToast('Authentication is not connected. This is a UI-only preview.')}}><Field label="Work email" placeholder="you@company.com" type="email"/>{!forgot&&<Field label="Password" placeholder="At least 8 characters" type="password"/>}{signup&&<Field label="Your name" placeholder="Alex Morgan"/>}{path==='/workspace/setup'&&<Field label="Workspace name" placeholder="Acme Studio"/>}{path==='/workspace/setup'&&<Field label="Work email" placeholder="you@company.com" type="email"/>}{path==='/login'&&<div className="auth-forgot"><Link href="/forgot-password">Forgot password?</Link></div>}<Button kind="primary">{config.button} <ArrowRight size={15}/></Button></form><div className="auth-switch">{signup?'Already have an account?':forgot?'Remember your password?':"New to Northstar?"} <Link href={signup?'/login':forgot?'/login':'/register'}>{signup||forgot?'Sign in':'Create an account'}</Link></div><div className="auth-prototype"><span className="prototype-dot"/> UI preview — no account will be created</div></div><div className="auth-legal">By continuing, you agree to our <button onClick={()=>setToast('Terms are not available in this preview.')}>Terms</button> and <button onClick={()=>setToast('Privacy policy is not available in this preview.')}>Privacy Policy</button>.</div></main><Toast message={toast} close={()=>setToast('')}/></div>;
}
export default App;
function Metric({title,value,delta,icon:Icon,accent}:{title:string;value:string;delta:string;icon:any;accent:string}) { return <div className="metric-card"><div className={`metric-icon ${accent}`}><Icon size={17}/></div><div className="metric-title">{title}</div><div className="metric-value">{value}</div><div className="metric-delta">{delta}</div></div>; }
function ActivityItem({initials,tone,text,sub,time}:{initials:string;tone:string;text:any;sub:string;time:string}) {return <div className="activity-item"><span className={`avatar avatar-${tone}`}>{initials}</span><div className="activity-text"><p>{text}</p><span>{sub}</span><small>{time}</small></div></div>;}

function Mailbox({path}:{path:string}) {
 const [,navigate]=useLocation();
 const [query,setQuery]=useState(new URLSearchParams(location.search).get('q')||sessionStorage.getItem('northstar-search-query')||'');
 const [filter,setFilter]=useState('All mail'); const [sort,setSort]=useState(false);
 const [selected,setSelected]=useState<string[]>([]); const [toast,setToast]=useState('');
 const [confirm,setConfirm]=useState('');
 const title=titles[path]; let rows=[...mails];
 if(path==='/starred')rows=rows.filter(m=>m.star);
 if(path==='/trash')rows=rows.slice(2,4);
 if(path==='/archive')rows=rows.slice(3);
 if(path==='/drafts')rows=rows.slice(1,4);
 if(path==='/sent')rows=rows.slice(4,8);
 rows=rows.filter(m=>`${m.sender} ${m.subject} ${m.preview} ${m.email}`.toLowerCase().includes(query.toLowerCase()));
 if(filter==='Unread')rows=rows.filter(m=>m.unread);
 if(filter==='High priority')rows=rows.filter(m=>m.priority==='High');
 if(sort)rows.reverse();
 const act=(action:string)=>{setConfirm('');setSelected([]);setToast(`${action} — preview only. No email data was changed.`);};
 return <><PageHeading eyebrow={path==='/inbox'?'SHARED INBOX':'MAIL'} title={title} description={descriptions[path]||'Work through conversations with your team, all in one place.'} actions={<Button kind="primary" icon={Plus} onClick={()=>navigate('/compose')}>Compose</Button>}/>
  {path==='/search'&&<div className="search-wide"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search people, subjects, messages…" autoFocus data-testid="input-mail-search"/><span>⌘ K</span></div>}
  <div className="mailbox-toolbar"><div className="toolbar-left"><button className="select-control" onClick={()=>setSelected(selected.length===rows.length?[]:rows.map(m=>m.id))} aria-label="Select all" data-testid="button-select-all"><span className={`checkbox ${selected.length===rows.length&&rows.length?'checked':''}`}>{selected.length===rows.length&&rows.length?<Check size={12}/>:null}</span><ChevronDown size={13}/></button><button className="icon-button" aria-label="Refresh preview" onClick={()=>setToast('Preview refreshed. Account data is static in this demo.')}><RefreshCw size={15}/></button><button className="icon-button" aria-label="Filter"><Filter size={15}/></button><select value={filter} onChange={e=>setFilter(e.target.value)} aria-label="Filter conversations" data-testid="select-mail-filter"><option>All mail</option><option>Unread</option><option>High priority</option></select>{selected.length>0&&<div className="bulk-actions"><span>{selected.length} selected</span><button onClick={()=>setConfirm('Archive selected conversations?')} aria-label="Archive selected"><Archive size={15}/></button><button onClick={()=>setConfirm('Mark selected as read?')} aria-label="Mark selected read"><MailOpen size={15}/></button><button onClick={()=>setConfirm('Delete selected conversations?')} aria-label="Delete selected"><Trash size={15}/></button></div>}</div><button className={`sort-button ${sort?'sort-active':''}`} onClick={()=>setSort(!sort)}><ArrowDownUp size={14}/> Newest first <ChevronDown size={13}/></button></div>
  <div className="mail-layout"><section className="panel mail-list-panel"><div className="mail-list-head"><span>{rows.length} conversations</span><span className="mail-list-accounts"><i style={{background:'#d65345'}}/> <i style={{background:'#3378c8'}}/> <i style={{background:'#6370b4'}}/> All accounts</span></div>{rows.length?rows.map(mail=><MailRow key={mail.id} mail={mail} selected={selected.includes(mail.id)} onSelect={()=>setSelected(selected.includes(mail.id)?selected.filter(x=>x!==mail.id):[...selected,mail.id])}/>):<div className="empty-state"><div className="empty-icon"><Search size={21}/></div><h3>No conversations found</h3><p>Try a different search or adjust your filters.</p><button className="text-link" onClick={()=>{setQuery('');setFilter('All mail')}}>Clear filters</button></div>}</section>
   <aside className="inbox-aside"><div className="panel inbox-summary"><div className="aside-title"><div><h3>Inbox health</h3><p>Across all accounts</p></div><Activity size={16}/></div><div className="health-score"><strong>98</strong><span>/ 100</span><b>Healthy</b></div><div className="health-line"><span/></div><div className="aside-stat"><span>Last sync</span><b>Just now</b></div><div className="aside-stat"><span>Open threads</span><b>38</b></div><div className="aside-stat"><span>Unassigned</span><b>6</b></div></div>
   <div className="panel ai-aside"><span className="ai-kicker"><Sparkles size={14}/> ASSISTED INSIGHT</span><h3>One quick win</h3><p>Two high-priority messages are waiting for a first reply. Start with Owen’s access issue.</p><Link href="/email/m-1047" className="text-link">Open conversation <ArrowRight size={14}/></Link><div className="ai-disclaimer">Suggestions are illustrative in this UI preview.</div></div>
   <div className="panel team-aside"><div className="aside-title"><div><h3>On your team</h3><p>4 members active today</p></div><Link href="/team" className="text-link">All</Link></div><div className="team-face-row">{team.map(m=><span key={m.email} className={`avatar avatar-${m.tone}`} title={m.name}>{m.initials}</span>)}<Link href="/team/invite" className="add-face"><Plus size={14}/></Link></div><div className="team-aside-note"><span className="sync-dot"/> 3 teammates online</div></div></aside></div>
  {confirm&&<div className="modal-backdrop"><div className="confirm-modal"><div className="modal-icon"><ShieldCheck size={19}/></div><h3>{confirm}</h3><p>This prototype won’t modify connected mail. You can safely preview this action.</p><div className="modal-actions"><Button onClick={()=>setConfirm('')}>Cancel</Button><Button kind="primary" onClick={()=>act(confirm.replace('?',''))}>Confirm preview</Button></div></div></div>}
  <Toast message={toast} close={()=>setToast('')}/>
 </>;
}

function MailRow({mail,compact=false,selected=false,onSelect}:{mail:any;compact?:boolean;selected?:boolean;onSelect?:()=>void}) {
 const [star,setStar]=useState(mail.star);
 return <div className={`mail-row ${mail.unread?'unread':''} ${compact?'compact':''} ${selected?'selected':''}`} data-testid={`row-conversation-${mail.id}`}>
   <button className={`checkbox ${selected?'checked':''}`} aria-label={`Select ${mail.subject}`} onClick={e=>{e.preventDefault();onSelect?.()}} data-testid={`checkbox-mail-${mail.id}`}>{selected&&<Check size={12}/>}</button>
   <button className={`star-button ${star?'is-starred':''}`} onClick={()=>setStar(!star)} aria-label={star?'Remove star':'Star conversation'} data-testid={`button-star-${mail.id}`}><Star size={15} fill={star?'currentColor':'none'}/></button>
   <span className={`provider-dot ${mail.provider==='Gmail'?'gmail':mail.provider==='IMAP'?'imap':'outlook'}`} title={`${mail.provider} · ${mail.account}`}>{mail.provider==='Gmail'?'G':mail.provider==='IMAP'?'I':'M'}</span>
   <Link href={`/email/${mail.id}`} className="mail-row-content" data-testid={`link-conversation-${mail.id}`}>
     <div className="mail-row-main"><b className="mail-sender">{mail.sender}</b><span className="mail-address">{mail.email}</span><span className="mail-time">{mail.time}</span></div>
     <div className="mail-subject-line"><span className="mail-subject">{mail.subject}</span>{mail.priority==='High'&&<span className="priority-mark"><Zap size={12}/> High</span>}{mail.attachment&&<Paperclip size={13} className="attachment-icon"/>}</div>
     <div className="mail-preview">{mail.preview}</div>
     <div className="mail-row-meta">{mail.labels.map((l:string)=><span className={`label-chip label-${l.toLowerCase().replaceAll(' ','-')}`} key={l}>{l}</span>)}<span className="assignment-meta"><span className={`avatar avatar-${mail.assigned==='Alex Morgan'?'blue':mail.assigned==='Priya Shah'?'peach':'mint'}`}>{mail.assigned==='Unassigned'?'–':mail.assigned.split(' ').map((x:string)=>x[0]).join('')}</span>{mail.assigned}</span></div>
   </Link>
 </div>;
}
function Toast({message,close}:{message:string;close:()=>void}) {
 return message?<div className="toast-message" role="status"><CheckCircle2 size={17}/><span>{message}</span><button onClick={close} aria-label="Dismiss message"><X size={15}/></button></div>:null;
}

function EmailDetail({id}:{id:string}) {
 const mail=mails.find(m=>m.id===id)||mails[0]; const [reply,setReply]=useState(false); const [note,setNote]=useState(false); const [toast,setToast]=useState('');
 return <><div className="detail-breadcrumb"><Link href="/inbox"><ArrowLeft size={15}/> Back to inbox</Link><div><button className="icon-button" aria-label="Previous conversation"><ChevronLeft size={17}/></button><button className="icon-button" aria-label="Next conversation"><ChevronRight size={17}/></button></div></div>
  <div className="detail-layout"><section className="panel detail-main"><div className="detail-toolbar"><div className="toolbar-left"><button className="icon-button" aria-label="Archive" onClick={()=>setToast('Archive is a UI-only preview action.')}><Archive size={16}/></button><button className="icon-button" aria-label="Delete" onClick={()=>setToast('Delete is a UI-only preview action.')}><Trash size={16}/></button><button className="icon-button" aria-label="Mark unread" onClick={()=>setToast('Unread state is illustrative in this preview.')}><MailOpen size={16}/></button><span className="toolbar-divider"/><button className="icon-button" aria-label="More actions"><Ellipsis size={18}/></button></div><Button icon={ArrowLeft} onClick={()=>setToast('Conversation is shown in the unified inbox.')}>Back</Button></div>
   <div className="thread-head"><div className="thread-tags">{mail.labels.map(l=><span className="label-chip" key={l}>{l}</span>)}<span className="priority-mark"><Zap size={12}/>{mail.priority} priority</span></div><h1>{mail.subject}</h1><div className="thread-account"><span className={`provider-dot ${mail.provider==='Gmail'?'gmail':mail.provider==='IMAP'?'imap':'outlook'}`}>{mail.provider==='Gmail'?'G':mail.provider==='IMAP'?'I':'M'}</span> via {mail.account}</div></div>
   <article className="message-card"><div className="message-head"><span className="avatar avatar-peach">{mail.sender.split(' ').map((x:string)=>x[0]).join('')}</span><div className="message-from"><b>{mail.sender}</b><span>&lt;{mail.email}&gt;</span><small>To: Alex Morgan · hello@northstar.studio</small></div><time>{mail.time} · Jun 17</time><button className="icon-button" aria-label="More message actions"><Ellipsis size={17}/></button></div><div className="message-body"><p>Hi Alex,</p><p>{mail.preview.replace('…','.')}</p><p>I’ve included a little more context below. Let me know if you’d like anything else from our side before we move forward.</p><p>Thanks,<br/>{mail.sender.split(' ')[0]}</p></div>{mail.attachment&&<div className="attachment-card"><span className="file-icon"><FileText size={18}/></span><span><b>{mail.attachment}</b><small>PDF document · 2.4 MB</small></span><button className="icon-button" aria-label="Download attachment"><Download size={16}/></button></div>}</article>
   <div className="thread-actions"><Button kind="primary" icon={Reply} onClick={()=>setReply(!reply)}>Reply</Button><Button icon={Forward} onClick={()=>setReply(true)}>Forward</Button><Button icon={StickyNote} onClick={()=>setNote(!note)}>Add internal note</Button></div>
   {reply&&<div className="inline-reply"><div className="reply-to"><Reply size={14}/> Replying to {mail.sender} <ChevronDown size={13}/></div><textarea placeholder="Write a reply…" aria-label="Reply message" data-testid="textarea-reply"/><div className="reply-bottom"><span>From: hello@northstar.studio</span><Button kind="primary" icon={Send} onClick={()=>setToast('Sending is disabled in this UI-only preview.')}>Send reply</Button></div></div>}
   {note&&<div className="inline-reply note-reply"><div className="reply-to"><StickyNote size={14}/> Private note for your team</div><textarea placeholder="Add context only your team can see…" aria-label="Internal note" data-testid="textarea-note"/><div className="reply-bottom"><span>Only visible to Northstar Studio</span><Button kind="primary" onClick={()=>{setNote(false);setToast('Note saved locally for this preview session.')}}>Add note</Button></div></div>}
   <div className="thread-history"><span className="history-line"/><span>Earlier in this conversation · Jun 14</span><div className="history-preview"><span className="avatar avatar-blue">AM</span><div><b>Alex Morgan</b><small>Thanks for sending this over. We’ll review with the team and come back to you tomorrow…</small></div><ChevronDown size={15}/></div></div>
  </section>
  <aside className="detail-aside"><div className="panel detail-side-panel"><div className="side-panel-title"><h3>Conversation details</h3><button className="icon-button"><Ellipsis size={17}/></button></div><DetailField label="Assigned to"><select defaultValue={mail.assigned} aria-label="Assigned teammate"><option>Unassigned</option>{team.map(t=><option key={t.email}>{t.name}</option>)}</select></DetailField><DetailField label="Priority"><span className={`priority-pill ${mail.priority.toLowerCase()}`}><i/>{mail.priority}</span></DetailField><DetailField label="Sentiment"><span className="sentiment-pill"><Smile size={14}/>{mail.sentiment}</span></DetailField><DetailField label="Labels"><div className="label-line">{mail.labels.map(l=><span className="label-chip" key={l}>{l}</span>)}<button className="tiny-add" aria-label="Add label"><Plus size={13}/></button></div></DetailField><DetailField label="Participants"><span>{mail.sender}<small>{mail.email}</small></span></DetailField><DetailField label="Account"><span>{mail.account}<small>{mail.provider}</small></span></DetailField></div>
   <div className="panel ai-summary-card"><span className="ai-kicker"><Sparkles size={13}/> AI SUMMARY · PREVIEW</span><p>{mail.summary}</p><button className="text-link" onClick={()=>setToast('AI actions are illustrative only. No model is connected.')}>Draft a reply <ArrowRight size={13}/></button><div className="ai-disclaimer">Suggested content needs human review.</div></div>
   <div className="panel detail-side-panel"><div className="side-panel-title"><h3>Related conversations</h3><span className="count-badge">2</span></div><Link href="/email/m-1044" className="related-item"><span className="related-mark"/> <span><b>Renewal options for 2025</b><small>Elliot Brooks · Yesterday</small></span><ChevronRight size={14}/></Link><Link href="/email/m-1045" className="related-item"><span className="related-mark"/> <span><b>Partnership launch timing</b><small>Nina Williams · 9:31 AM</small></span><ChevronRight size={14}/></Link></div>
   <div className="panel activity-mini"><h3>Activity</h3><ActivityItem initials="AM" tone="blue" text={<><b>Alex Morgan</b> opened this</>} sub="" time="2 min ago"/><ActivityItem initials="PS" tone="peach" text={<><b>Priya Shah</b> assigned to Alex</>} sub="" time="4 min ago"/></div>
  </aside></div><Toast message={toast} close={()=>setToast('')}/></>;
}
function DetailField({label,children}:{label:string;children:any}) {return <div className="detail-field"><span>{label}</span><div>{children}</div></div>;}

function Compose() {
 const [cc,setCc]=useState(false);const [bcc,setBcc]=useState(false);const [toast,setToast]=useState('');const [schedule,setSchedule]=useState(false);const [from,setFrom]=useState(accounts[0].address);
 return <><PageHeading eyebrow="COMPOSE" title="New message" description="Write from the right account, with your team close by." actions={<Button onClick={()=>setToast('Draft saved locally for this preview session.')}>Save draft</Button>}/>
 <div className="compose-wrap"><section className="panel compose-panel"><div className="compose-account-row"><label>From</label><select value={from} onChange={e=>setFrom(e.target.value)} aria-label="Sending account" data-testid="select-compose-account">{accounts.map(a=><option key={a.address}>{a.address}</option>)}</select><button className="text-link" onClick={()=>setToast('Account management is available in Email accounts.')}>Manage accounts</button></div>
  <div className="compose-line"><label htmlFor="compose-to">To</label><input id="compose-to" placeholder="Add recipients" data-testid="input-compose-to"/><span><button onClick={()=>setCc(!cc)}>Cc</button><button onClick={()=>setBcc(!bcc)}>Bcc</button></span></div>
  {cc&&<div className="compose-line"><label htmlFor="compose-cc">Cc</label><input id="compose-cc" placeholder="Add Cc recipients" data-testid="input-compose-cc"/></div>}
  {bcc&&<div className="compose-line"><label htmlFor="compose-bcc">Bcc</label><input id="compose-bcc" placeholder="Add Bcc recipients" data-testid="input-compose-bcc"/></div>}
  <div className="compose-line"><label htmlFor="compose-subject">Subject</label><input id="compose-subject" placeholder="Add a subject" data-testid="input-compose-subject"/></div>
  <div className="editor-tools"><button aria-label="Bold"><Bold size={15}/></button><button aria-label="Italic"><Italic size={15}/></button><span/><button aria-label="Attach file" onClick={()=>setToast('File attachments are visual only in this preview.')}><Paperclip size={15}/></button><button aria-label="Insert link"><Link2 size={15}/></button><button aria-label="Schedule send" onClick={()=>setSchedule(!schedule)}><CalendarClock size={15}/></button><button className="ai-editor-button" onClick={()=>setToast('AI suggestions are not connected in this prototype.')}><Sparkles size={14}/> Draft with AI</button></div>
  <div className="compose-editor" contentEditable suppressContentEditableWarning data-placeholder="Write your message…" data-testid="editor-compose" role="textbox" aria-label="Message body"/>
  {schedule&&<div className="schedule-strip"><CalendarDays size={16}/><span>Schedule for</span><input type="date" aria-label="Schedule date"/><input type="time" aria-label="Schedule time" defaultValue="09:00"/><button onClick={()=>setToast('Scheduling requires a connected sending service.')}>Set schedule</button></div>}
  <div className="compose-footer"><div><Button kind="primary" icon={Send} onClick={()=>setToast('Sending is disabled. Connect a sending service to send real email.')}>Send <ChevronDown size={13}/></Button><button className="icon-button" aria-label="Attach a file" onClick={()=>setToast('File attachments are visual only in this preview.')}><Paperclip size={16}/></button><button className="icon-button" aria-label="Insert link"><Link2 size={16}/></button></div><span>From {from}</span></div>
 </section><aside className="compose-aside"><div className="panel ai-aside"><span className="ai-kicker"><Sparkles size={13}/> WRITING ASSISTANT</span><h3>A second set of eyes</h3><p>Drafting tools can help with tone and clarity. You stay in control of every word.</p><Button onClick={()=>setToast('AI suggestions are not connected in this prototype.')}>Suggest a reply</Button><div className="ai-disclaimer">No message content is processed in this UI preview.</div></div><div className="panel compose-tip"><h3>Before you send</h3><ul><li><Check size={14}/> Double-check recipients</li><li><Check size={14}/> Pick the right shared account</li><li><Check size={14}/> Keep teammates in the loop</li></ul></div></aside></div><Toast message={toast} close={()=>setToast('')}/></>;
}

const ruleRows=[
 {name:'VIP customer routing',trigger:'New conversation',condition:'Contact tag is VIP',action:'Assign to Priya Shah',enabled:true,last:'Today, 10:32 AM'},
 {name:'Triage support requests',trigger:'New conversation',condition:'Subject contains “help”',action:'Apply Support label',enabled:true,last:'Today, 9:48 AM'},
 {name:'Flag urgent language',trigger:'Message received',condition:'Priority signals detected',action:'Mark as high priority',enabled:true,last:'Today, 9:14 AM'},
 {name:'Close resolved threads',trigger:'Conversation updated',condition:'Status is resolved',action:'Move to Archive',enabled:false,last:'Yesterday, 4:05 PM'}
];
function DataPage({path}:{path:string}) {
 const [,navigate]=useLocation();
 const [toast,setToast]=useState('');const [search,setSearch]=useState('');const [enabled,setEnabled]=useState<Record<string,boolean>>({});const [dialog,setDialog]=useState(false);
 const title=titles[path]||'Workspace'; const description=descriptions[path]||'A clear view of the tools and controls that keep your shared workspace in sync.';
 const showToast=(msg:string)=>setToast(msg);
 if(path.startsWith('/accounts/connect/')) return <><PageHeading eyebrow="EMAIL ACCOUNTS" title={title} description="Connect an inbox to see how it will fit into your team workspace." actions={<Link href="/accounts" className="button button-secondary"><ArrowLeft size={15}/> Accounts</Link>}/><div className="connect-layout"><div className="panel connect-card"><div className="connect-provider-logo">{path.endsWith('gmail')?'G':path.endsWith('outlook')?'M':'I'}</div><h2>{path.endsWith('gmail')?'Gmail':path.endsWith('outlook')?'Microsoft 365':'IMAP / SMTP'}</h2><p>{path.endsWith('imap')?'Add your email address and server details to preview the IMAP setup.':'Connect a team inbox to bring its conversations into the shared workspace.'}</p>{path.endsWith('imap')?<div className="imap-fields"><Field label="Email address" placeholder="you@company.com"/><Field label="IMAP server" placeholder="imap.company.com"/><Field label="SMTP server" placeholder="smtp.company.com"/><div className="form-two"><Field label="Username" placeholder="Email username"/><Field label="Password" placeholder="••••••••"/></div></div>:<div className="permission-box"><ShieldCheck size={18}/><div><b>Secure connection</b><span>This UI preview does not request OAuth permissions or connect to a provider.</span></div></div>}<Button kind="primary" onClick={()=>showToast('Account connection requires a real backend and provider authorization.')}>{path.endsWith('imap')?'Preview account details':'Continue to provider'}</Button><div className="connect-note">No account will be connected in this prototype.</div></div><div className="connect-benefits"><h3>What happens next?</h3><div><span>01</span><p><b>Choose an inbox</b><small>Select the account your team uses to collaborate.</small></p></div><div><span>02</span><p><b>Set access and ownership</b><small>Pick the teammates who can view and manage conversations.</small></p></div><div><span>03</span><p><b>Start in one shared queue</b><small>Your connected accounts stay identifiable at every step.</small></p></div></div></div><Toast message={toast} close={()=>setToast('')}/></>;
 const goAdd=()=>navigate('/accounts/add');
 const isSettings=path.startsWith('/settings');
 const accountPage=path==='/accounts'||path==='/settings/accounts';
 const teamPage=path==='/team';
 const rolesPage=path==='/team/roles';
 const invitePage=path==='/team/invite';
 const rulePage=path.startsWith('/automation')||path==='/settings/automation';
 const aiPage=path.startsWith('/ai')||path==='/settings/ai';
 const contactPage=path==='/contacts';
 const templatePage=path==='/templates';
 const notePage=path==='/internal-notes';
 const assignmentPage=path==='/assignment';
 const webhookPage=path==='/webhooks';
 const schedulePage=path==='/automation/scheduled-actions';
 const notificationPage=path==='/notifications';
 const usagePage=path==='/settings/usage';
 const auditPage=path==='/settings/audit-logs';
 const connectAdd=path==='/accounts/add';
 const profileForm=path.startsWith('/settings')&&!accountPage&&!usagePage&&!auditPage&&!aiPage&&!rulePage;
 let rows:any[]=[];
 if(teamPage)rows=team;
 if(accountPage)rows=accounts;
 if(contactPage)rows=[{name:'Maya Chen',email:'maya@fieldnotes.co',company:'Fieldnotes',last:'Today, 10:42 AM',conversations:8},{name:'Owen Park',email:'owen.park@clearwater.io',company:'Clearwater',last:'Today, 10:18 AM',conversations:4},{name:'Nina Williams',email:'nina@lumenhouse.com',company:'Lumen House',last:'Today, 9:31 AM',conversations:6},{name:'Elliot Brooks',email:'elliot@brightpath.org',company:'Brightpath',last:'Yesterday',conversations:3}];
 if(templatePage)rows=[{name:'Thanks for reaching out',category:'Support',updated:'Jun 12, 2025',usage:42},{name:'Following up on your proposal',category:'Sales',updated:'Jun 11, 2025',usage:18},{name:'We received your request',category:'Support',updated:'Jun 09, 2025',usage:76},{name:'Project handoff',category:'Client success',updated:'Jun 06, 2025',usage:11}];
 return <><PageHeading eyebrow={isSettings?'PREFERENCES':aiPage?'INTELLIGENCE':rulePage?'AUTOMATION':undefined} title={title} description={description} actions={headingAction(path,()=>setDialog(true),goAdd,showToast)}/>
  {isSettings&&<div className="settings-tabs">{navGroups[6].items.map(([href,label])=><Link className={href===path?'selected':''} href={href} key={href}>{label}</Link>)}</div>}
  {connectAdd&&<div className="provider-grid">{[['gmail','Gmail','Connect a Google Workspace or Gmail inbox','G'],['outlook','Microsoft 365','Connect an Outlook or Microsoft 365 inbox','M'],['imap','IMAP / SMTP','Bring another mailbox with custom server details','I']].map(([slug,name,copy,mark])=><Link href={`/accounts/connect/${slug}`} className="panel provider-choice" key={slug}><span className={`provider-choice-mark ${slug}`}>{mark}</span><span><b>{name}</b><small>{copy}</small></span><ArrowRight size={16}/></Link>)}<div className="connect-footnote"><ShieldCheck size={15}/> Provider connections are UI-only. No OAuth or mailbox access is requested.</div></div>}
  {accountPage&&<><div className="account-cards">{accounts.map(a=><div className="panel account-card" key={a.address}><div className="account-card-top"><span className="provider-mark" style={{'--provider':a.color} as any}>{a.provider==='Gmail'?'G':a.provider==='IMAP / SMTP'?'I':'M'}</span><span className="status-pill"><i/>{a.status}</span><button className="icon-button" aria-label="Account options"><Ellipsis size={16}/></button></div><h3>{a.address}</h3><p>{a.provider} · Shared inbox</p><div className="account-card-stats"><span><b>{a.count}</b><small>Synced messages</small></span><span><b>{a.sync}</b><small>Last sync</small></span></div><div className="account-card-footer"><span><span className="sync-dot"/> Sync healthy</span><button className="text-link" onClick={()=>showToast('Account settings are a UI-only preview.')}>Settings <ArrowRight size={13}/></button></div></div>)}</div><div className="panel account-privacy"><ShieldCheck size={18}/><div><b>Your accounts stay distinct</b><p>Provider and address indicators stay visible in the unified inbox. Connecting accounts is disabled in this prototype.</p></div><Button onClick={goAdd}>Add account</Button></div></>}
  {teamPage&&<DataTable kind="team" rows={rows} onAction={showToast} query={search} setQuery={setSearch}/>}
  {rolesPage&&<RolesTable onAction={showToast}/>}
  {invitePage&&<div className="panel invite-panel"><div className="invite-icon"><UserPlus size={21}/></div><h2>Bring your team into the loop</h2><p>Invite teammates to collaborate across Northstar Studio’s shared inboxes.</p><div className="invite-input-row"><input placeholder="name@company.com" aria-label="Teammate email" data-testid="input-invite-email"/><select aria-label="Invite role"><option>Agent</option><option>Manager</option><option>Admin</option></select><Button kind="primary" onClick={()=>showToast('Invitations require a connected workspace backend.')}>Send invite</Button></div><div className="invite-note"><LockKeyhole size={14}/> Invites are not sent in this UI preview.</div><div className="pending-invites"><h3>Pending invitations <span className="count-badge">2</span></h3><div><span className="avatar avatar-peach">EC</span><span><b>emma@northstar.studio</b><small>Agent · Sent yesterday</small></span><span className="pending-label">Pending</span><button onClick={()=>showToast('Invite management is a UI-only preview.')}>Resend</button></div><div><span className="avatar avatar-mint">RK</span><span><b>ravi@northstar.studio</b><small>Manager · Sent Jun 14</small></span><span className="pending-label">Pending</span><button onClick={()=>showToast('Invite management is a UI-only preview.')}>Resend</button></div></div></div>}
  {rulePage&&<>{path==='/automation'||path==='/settings/automation'?<div className="rule-summary-row"><Metric title="Active rules" value="3" delta="1 paused" icon={Workflow} accent="blue"/><Metric title="Rule activity" value="47" delta="This week · preview only" icon={Activity} accent="green"/><Metric title="Next scheduled" value="2:30 PM" delta="Snooze follow-up" icon={CalendarClock} accent="amber"/></div>:null}<div className="panel table-panel"><div className="table-toolbar"><div><b>{schedulePage?'Scheduled actions':'Rules'}</b><span>{schedulePage?'2 actions queued in preview':'Small automations for repeatable work'}</span></div><div className="table-toolbar-actions"><Button onClick={()=>showToast('Rule controls are preview-only. No automation can run here.')}>View activity</Button><Button kind="primary" icon={Plus} onClick={()=>setDialog(true)}>{schedulePage?'Schedule action':'Create rule'}</Button></div></div>{schedulePage?<ScheduleList onAction={showToast}/>:<div className="rule-list">{ruleRows.map((r,i)=><div className="rule-row" key={r.name}><span className="rule-icon"><Workflow size={17}/></span><div className="rule-main"><b>{r.name}</b><small>{r.trigger} <ArrowRight size={11}/> {r.condition} <ArrowRight size={11}/> {r.action}</small></div><span className="rule-run">{r.last}</span><button className={`switch ${enabled[r.name]??r.enabled?'on':''}`} role="switch" aria-checked={enabled[r.name]??r.enabled} onClick={()=>{setEnabled({...enabled,[r.name]:!(enabled[r.name]??r.enabled)});showToast('Rule toggle is local only. No automation executed.')}} aria-label={`Toggle ${r.name}`} data-testid={`switch-rule-${i}`}><i/></button><button className="icon-button" aria-label={`More options for ${r.name}`}><Ellipsis size={17}/></button></div>)}</div>}</div><div className="automation-disclaimer"><Zap size={15}/><span><b>Preview mode</b> — rules can be inspected here, but no message is routed, changed, or acted on.</span></div></>}
  {aiPage&&<AIContent path={path} onAction={showToast}/>}
  {contactPage&&<DataTable kind="contacts" rows={rows} onAction={showToast} query={search} setQuery={setSearch}/>}
  {templatePage&&<DataTable kind="templates" rows={rows} onAction={showToast} query={search} setQuery={setSearch}/>}
  {notePage&&<NotesPage onAction={showToast}/>}
  {assignmentPage&&<AssignmentPage onAction={showToast}/>}
  {webhookPage&&<WebhookPage onAction={showToast}/>}
  {notificationPage&&<NotificationPage onAction={showToast}/>}
  {usagePage&&<UsagePage/>}
  {auditPage&&<AuditPage/>}
  {profileForm&&<SettingsForm path={path} onAction={showToast}/>}
  {rolesPage===false&&!teamPage&&!accountPage&&!invitePage&&!rulePage&&!aiPage&&!contactPage&&!templatePage&&!notePage&&!assignmentPage&&!webhookPage&&!notificationPage&&!usagePage&&!auditPage&&!profileForm&&!connectAdd&&<GenericPage path={path} onAction={showToast}/>}
  {dialog&&<div className="modal-backdrop"><div className="confirm-modal"><button className="modal-close" onClick={()=>setDialog(false)} aria-label="Close"><X size={16}/></button><div className="modal-icon"><Workflow size={19}/></div><h3>{rulePage?'Create an automation rule':'Create a new item'}</h3><p>Editing and execution require a connected workspace backend. This demo is safe to explore.</p><Field label="Name" placeholder="Give this a clear name"/><div className="modal-actions"><Button onClick={()=>setDialog(false)}>Cancel</Button><Button kind="primary" onClick={()=>{setDialog(false);showToast('Saved state is unavailable in this UI-only preview.')}}>Continue</Button></div></div></div>}
  <Toast message={toast} close={()=>setToast('')}/>
 </>;
}
